public class Main {
    public static void main(String[] args) {
        int[][] a = {{2, 4}, {3}};
        // 바깥 배열만 새로 만들어요. 안쪽 배열은 아직 a와 함께 써요.
        int[][] b = a.clone();
        // 이 주석 아래 줄에 b의 첫 안쪽 배열을 따로 복사하세요.
