class Stock {
    int count;
    // 각 객체의 재고 값을 따로 준비해요.
    Stock(int count) { this.count = count; }
}
class Changes {
    static Stock replace(Stock value, int fresh) {
        // 인수 이름만 새 객체로 연결하고 그 참조값을 반환해요.
        value = new Stock(fresh);
        return value;
    }
}

public class Main {
    public static void main(String[] args) {
